/**
 * ERC-8056 (Scaled UI Amount) ABI fragments.
 *
 * Based on the `IScaledUIAmount` interface from the BNB Chain partner integration doc
 * v1.0 (8 Apr 2026). The spec itself is in Draft as of Oct 2025; these fragments are
 * pinned against the concrete implementation Binance is deploying for Stock Tokens.
 *
 * Spec: https://eips.ethereum.org/EIPS/eip-8056
 *
 * Notes:
 * - `newUIMultiplier` and `effectiveAt` are optional getters in the spec. Real
 *   implementations may or may not expose them — reads must use `allowFailure: true`.
 * - `totalSupplyUI()` does NOT exist on Binance Stock Tokens per the partner doc FAQ;
 *   compute as `toUIAmount(totalSupply())` instead.
 * - All on-chain helpers (`toUIAmount`, `fromUIAmount`, `balanceOfUI`) match the
 *   contract's rounding exactly; prefer them over JS math when available.
 */
export const scaledUIAmountAbi = [
  // ─── Core required interface (ERC-165 ID: 0xa60bf13d) ───
  {
    type: 'function',
    name: 'uiMultiplier',
    inputs: [],
    outputs: [{ type: 'uint256' }],
    stateMutability: 'view',
  },
  {
    type: 'function',
    name: 'toUIAmount',
    inputs: [{ name: 'rawAmount', type: 'uint256' }],
    outputs: [{ type: 'uint256' }],
    stateMutability: 'view',
  },
  {
    type: 'function',
    name: 'fromUIAmount',
    inputs: [{ name: 'uiAmount', type: 'uint256' }],
    outputs: [{ type: 'uint256' }],
    stateMutability: 'view',
  },

  // ─── Balances extension (ERC-165 ID: 0xd890fd71) ───
  {
    type: 'function',
    name: 'balanceOfUI',
    inputs: [{ name: 'account', type: 'address' }],
    outputs: [{ type: 'uint256' }],
    stateMutability: 'view',
  },

  // ─── Pending-change getters (optional in spec; common in implementations) ───
  {
    type: 'function',
    name: 'newUIMultiplier',
    inputs: [],
    outputs: [{ type: 'uint256' }],
    stateMutability: 'view',
  },
  {
    type: 'function',
    name: 'effectiveAt',
    inputs: [],
    outputs: [{ type: 'uint256' }],
    stateMutability: 'view',
  },

  // ─── Events ───
  // Both timestamps required per BNB doc §4.1
  {
    type: 'event',
    name: 'UIMultiplierUpdated',
    inputs: [
      { name: 'oldMultiplier', type: 'uint256', indexed: false },
      { name: 'newMultiplier', type: 'uint256', indexed: false },
      { name: 'setAtTimestamp', type: 'uint256', indexed: false },
      { name: 'effectiveAtTimestamp', type: 'uint256', indexed: false },
    ],
  },
  // Optional event — emits raw + UI in one record (lets activity history show both
  // without re-deriving from the current multiplier)
  {
    type: 'event',
    name: 'TransferWithUIAmount',
    inputs: [
      { name: 'from', type: 'address', indexed: true },
      { name: 'to', type: 'address', indexed: true },
      { name: 'amount', type: 'uint256', indexed: false },
      { name: 'uiAmount', type: 'uint256', indexed: false },
    ],
  },
] as const
