// EVM-side ScaledUI utilities — ERC-165 detection and multicall metadata fetcher.
// Pure functions, no React; the app layer wires react-query + caching on top.

import { SCALED_UI_DENOMINATOR } from '@pancakeswap/swap-sdk-core'
import type { Address, PublicClient } from 'viem'
import { erc165Abi } from './abis/ERC165'
import { scaledUIAmountAbi } from './abis/ScaledUIAmount'

/**
 * ERC-8056 ERC-165 interface IDs.
 *
 * Pinned in the BNB Chain partner integration doc v1.0 (8 Apr 2026). The spec lists
 * "others TBD" for the optional conversion / new-multiplier sub-interfaces — do not
 * rely on those IDs being stable until the spec moves out of Draft status.
 */
export const SCALED_UI_AMOUNT_INTERFACE_ID = '0xa60bf13d' as const
export const SCALED_UI_AMOUNT_BALANCES_INTERFACE_ID = '0xd890fd71' as const

/**
 * Live ScaledUI metadata for a token, fetched from chain.
 *
 * The single join point between tokenlist `extensions.scaledUIAmount.enabled` and the
 * on-chain multiplier state. Consumers should treat `{ enabled: false, multiplier: 1e18 }`
 * as the identity case and early-out from any scaling logic.
 */
export type ScaledUIAmountMetadata = {
  /** True if the contract implements ERC-8056's `uiMultiplier()`. */
  enabled: boolean
  /** Currently active multiplier (18-decimal fixed point). Defaults to `1e18` (identity). */
  multiplier: bigint
  /** Pending scheduled multiplier (only present when an upcoming change is announced). */
  newMultiplier?: bigint
  /** Unix timestamp (seconds) at which the pending change activates. */
  effectiveAt?: number
}

/**
 * The identity metadata — returned for non-scaled tokens and on any read failure.
 * Safe default: behaves like a normal ERC-20 in every downstream calculation.
 */
export const IDENTITY_SCALED_UI_AMOUNT_METADATA: ScaledUIAmountMetadata = {
  enabled: false,
  multiplier: SCALED_UI_DENOMINATOR,
}

/**
 * Probe a token contract for ERC-8056 support via ERC-165 `supportsInterface(0xa60bf13d)`.
 *
 * Returns `false` on any error (contract doesn't implement ERC-165, RPC failure, etc.) —
 * the caller is responsible for caching positive AND negative results with appropriate
 * TTL (see ticket memory: asymmetric 6-month/30-day cache in IndexedDB).
 *
 * Note: this is a perf-optimisation probe, not a correctness gate. Even if it returns
 * a stale "yes", `fetchScaledUIAmountMetadata` below will gracefully fall back to the
 * identity metadata if the actual contract calls revert.
 */
export async function probeIsScaledUIAmount(client: PublicClient, address: Address): Promise<boolean> {
  try {
    const result = await client.readContract({
      address,
      abi: erc165Abi,
      functionName: 'supportsInterface',
      args: [SCALED_UI_AMOUNT_INTERFACE_ID],
    })
    return Boolean(result)
  } catch {
    return false
  }
}

/**
 * Fetch live ScaledUI metadata for a token via a single multicall.
 *
 * Defensive read posture:
 * - All three reads use `allowFailure: true`.
 * - If `uiMultiplier()` fails, treats the token as non-scaled (identity metadata).
 * - If only the pending getters fail (common — they're optional in the spec), returns
 *   the active multiplier without pending-change info.
 *
 * Use this in concert with the IndexedDB ERC-165 cache to skip the call entirely for
 * tokens we know aren't 8056. But even without the cache, this function is safe to
 * call against any contract — it won't throw.
 */
export async function fetchScaledUIAmountMetadata(
  client: PublicClient,
  address: Address,
): Promise<ScaledUIAmountMetadata> {
  const results = await client.multicall({
    contracts: [
      { address, abi: scaledUIAmountAbi, functionName: 'uiMultiplier' },
      { address, abi: scaledUIAmountAbi, functionName: 'newUIMultiplier' },
      { address, abi: scaledUIAmountAbi, functionName: 'effectiveAt' },
    ],
    allowFailure: true,
  })

  const [activeRes, pendingMRes, pendingTsRes] = results

  if (activeRes.status !== 'success') {
    return IDENTITY_SCALED_UI_AMOUNT_METADATA
  }

  const multiplier = activeRes.result as bigint
  // Defensive: 0 is an invalid multiplier per ERC-8056 but a buggy / malicious
  // contract could return it. Treat as a read failure so downstream math doesn't
  // collapse displayed amounts to 0 or hit a bigint divide-by-zero.
  if (multiplier === 0n) {
    return IDENTITY_SCALED_UI_AMOUNT_METADATA
  }
  const newMultiplier = pendingMRes.status === 'success' ? (pendingMRes.result as bigint) : undefined
  const effectiveAtRaw = pendingTsRes.status === 'success' ? (pendingTsRes.result as bigint) : undefined
  const effectiveAt = effectiveAtRaw !== undefined ? Number(effectiveAtRaw) : undefined

  // No "pending change" if newMultiplier matches current OR effectiveAt is unset/zero.
  const hasPending =
    newMultiplier !== undefined && effectiveAt !== undefined && newMultiplier !== multiplier && effectiveAt > 0

  return hasPending ? { enabled: true, multiplier, newMultiplier, effectiveAt } : { enabled: true, multiplier }
}

// Re-export the math primitives so consumers can `import from '@pancakeswap/swap-sdk-evm'`
// for one-stop access to detection + math.
export {
  SCALED_UI_DENOMINATOR,
  SCALED_UI_MULTIPLIER_DECIMALS,
  fromScaledUIAmount,
  isIdentityScaledUIMultiplier,
  toScaledUIAmount,
} from '@pancakeswap/swap-sdk-core'
